"""Persisted code-generation loop. Submission is irrevocable before scoring."""
from copy import deepcopy
import json
from pathlib import Path
import shutil
import time
import uuid
from ...storage import write_record
from . import protocol, executor, scoring, transport


class Interrupted(RuntimeError):
    pass


class GenerationExhausted(Interrupted):
    """No executable program was produced; this is not a graded submission."""


def run(task, skill, directory, config, *, generate=None, execute=None, score=None, clock=time.monotonic, hook=None):
    directory=Path(directory).resolve();directory.mkdir(parents=True,exist_ok=True)
    state_file=directory/'actor_state.json';result_file=directory/'trajectory.json'
    profile=config['actor_profile'];generate=generate or transport.request;execute=execute or executor.execute;score=score or scoring.score
    separate=protocol.separate_budgets(profile)
    isolated=protocol.execution_history(profile)
    if isolated and (not separate or profile['actor_task_timeout_seconds']!=0):
        raise protocol.InputError('Execution-only history requires execution budgets and no cumulative task deadline')
    active_started=None;budget_frozen=False
    def save():
        if active_started is not None and not budget_frozen:
            state['elapsed_seconds']=elapsed_before+max(0,clock()-active_started)
        if separate:
            state.update(code_attempts=sum(bool(a.get('execution_started')) for a in state['attempts']),
                         program_executions=sum(a['executed'] for a in state['attempts']),
                         generation_responses=len(state['attempts']),api_requests=len(state['requests']))
        write_record(state_file,state)
    if state_file.exists():
        state=json.loads(state_file.read_text())
        if (state['task']!=task or state['skill']!=skill or state['protocol']!=profile or state['model']!=config['actor_model']):
            raise Interrupted('Saved Actor conditions differ')
        if state.get('pending'):
            spent=max(0,time.time()-state['pending']['wall_started']);limit=state['pending']['limit']
            state['elapsed_seconds']+=spent if limit is None else min(spent,limit)
            state['pending']=None;save()
    else:
        state=dict(version='v25_spreadsheet_actor_v1',run_id='run_'+uuid.uuid4().hex,task=deepcopy(task),skill=skill,
            model=config['actor_model'],protocol=deepcopy(profile),executor=deepcopy(config['executor']),
            attempts=[],requests=[],messages=[],elapsed_seconds=0.,pending=None,actor_complete=False,status='running')
        if isolated:state['format_repair']=None
        save()
    elapsed_before=state['elapsed_seconds'];active_started=clock();budget_frozen=state['actor_complete']
    def remaining():
        if profile['actor_task_timeout_seconds']==0:return float('inf')
        return max(0,profile['actor_task_timeout_seconds']-elapsed_before-max(0,clock()-active_started))
    def checkpoint(name):
        if hook:hook(name,state)
    def operation(kind,limit,fn):
        if limit is not None and limit<=0:raise Interrupted('No remaining Actor time')
        state['pending']={'kind':kind,'wall_started':time.time(),'limit':limit};save()
        try:return fn()
        finally:
            state['pending']=None;save()
    try:
        if state.get('status')=='completed':
            budget_frozen=True
            if not result_file.exists():write_record(result_file,state)
            return result_file
        if not state['messages']:
            def prepare():
                snapshot=directory/'original_input.xlsx'
                if snapshot.exists():
                    if snapshot.read_bytes()!=Path(task['input_path']).read_bytes():raise protocol.InputError('Original input changed')
                else:shutil.copyfile(task['input_path'],snapshot)
                state['input_snapshot']=str(snapshot)
                view=protocol.preview(snapshot,profile)
                state['workbook_preview']=view
                state['messages']=protocol.initial_messages(task,skill,view,profile)
                state['initial_messages']=deepcopy(state['messages']);save()
            operation('input_preparation',None if profile['actor_task_timeout_seconds']==0 else remaining(),prepare)
        while not state['actor_complete']:
            unprocessed=state['attempts'] and not state['attempts'][-1].get('processed')
            if not unprocessed:
                number=len(state['attempts'])+1;response=None
                used=sum(bool(a.get('execution_started')) for a in state['attempts']) if separate else len(state['attempts'])
                slot=used+1
                prior=[r for r in state['requests'] if r['code_attempt']==slot]
                consumed={a.get('request_path') for a in state['attempts']} if separate else set()
                for item in prior:
                    if item['path'] in consumed:continue
                    folder=directory/item['path']
                    if item.get('response') is None and (folder/'response.json').exists():
                        item['response']=json.loads((folder/'response.json').read_text());save()
                    if item.get('response') is not None:response=item['response'];break
                # Resolve saved responses before classifying an exhausted task.
                # An unanswered API request remains a technical interruption on
                # resume; it must not become a scored failure in learning/Gate.
                if prior and response is None and remaining()<=0:
                    raise Interrupted('API unavailable before task deadline')
                if used>=profile['max_code_attempts'] or remaining()<=0:
                    state.update(actor_complete=True,termination='budget_exhausted',submitted_attempt=None,output_path=None);save();break
                messages=protocol.generation_messages(state['messages'],state['format_repair']) if isolated else deepcopy(state['messages'])
                protocol.check_capacity(messages,config)
                if response is None:
                    if prior and prior[-1].get('retryable') is False:raise Interrupted('Preserved non-retryable API failure')
                    for request_number in range(len(prior)+1,profile['request_attempts_total']+1):
                        if remaining()<=0:raise Interrupted('API unavailable before task deadline')
                        path=directory/'requests'/f'{slot:03}_{request_number:02}';path.mkdir(parents=True,exist_ok=True)
                        item={'code_attempt':slot,'path':str(path.relative_to(directory)),'response':None}
                        if isolated:item['messages']=deepcopy(messages)
                        state['requests'].append(item);save()
                        write_record(path/'messages.json',messages)
                        def call():
                            value=generate(deepcopy(messages),path,min(profile['request_timeout_seconds'],remaining()),config)
                            if not isinstance(value,dict) or not isinstance(value.get('content'),str):raise transport.RequestError('Malformed model response')
                            write_record(path/'response.json',value);return value
                        try:
                            response=operation('api_request',min(profile['request_timeout_seconds'],remaining()),call)
                            item['response']=response;save();checkpoint('response_saved');break
                        except transport.RequestError as exc:
                            item.update(error=str(exc),retryable=exc.retryable);save()
                            if not exc.retryable:raise Interrupted(str(exc)) from exc
                            if request_number<profile['request_attempts_total'] and remaining()>0:
                                delay=min(config.get('retry_delay_seconds',0)*request_number,remaining())
                                if delay:operation('retry_wait',delay,lambda:time.sleep(delay))
                    if response is None:
                        if separate:raise GenerationExhausted('Generation request budget exhausted; resume does not reset it')
                        raise Interrupted('Frozen API attempts exhausted; resume does not reset them')
                attempt={'number':number,'request_messages':deepcopy(item['messages'] if isolated else state['messages']),'response':response['content'],
                         'finish_reason':response.get('finish_reason'),'executed_code':None,'executed':False,
                         'execution':None,'feedback_to_actor':None,'processed':False}
                if separate:
                    attempt.update(request_path=item['path'],code_attempt=slot,
                                   response_in_history=not isolated and response.get('finish_reason')=='stop')
                if isolated:attempt['repair_feedback']=None
                state['attempts'].append(attempt)
                if attempt.get('response_in_history',True):
                    state['messages'].append({'role':'assistant','content':response['content']})
                save()
            attempt=state['attempts'][-1];number=attempt['number'];folder=directory/'code'/f'{number:03}';folder.mkdir(parents=True,exist_ok=True)
            if (folder/'execution.json').exists():
                attempt['execution']=json.loads((folder/'execution.json').read_text());attempt['executed']=True
                attempt['executed_code']=(folder/'program.py').read_text()
            if attempt['execution'] is None:
                if separate and attempt['finish_reason'] not in ('stop','length'):
                    raise Interrupted(f"Non-retryable model finish reason: {attempt['finish_reason']}")
                try:
                    if attempt['finish_reason']!='stop':raise ValueError('Model generation did not finish normally; return a complete program')
                    if isolated and not attempt['response'].strip():raise ValueError('Model returned an empty response')
                    raw,actual=protocol.extract_code(attempt['response']);(folder/'raw.py').write_text(raw);(folder/'program.py').write_text(actual)
                except (ValueError,SyntaxError) as exc:
                    category='generation_truncated' if separate and attempt['finish_reason']=='length' else 'format_error'
                    if isolated and attempt['finish_reason']=='stop' and not attempt['response'].strip():category='empty_output'
                    attempt['execution']={'status':category,'error_category':category,'error_detail':str(exc),'exit_status':'not_executed','output_openable':False}
                else:
                    if remaining()<=0:
                        state.update(actor_complete=True,termination='budget_exhausted',submitted_attempt=None,output_path=None);save();break
                    if attempt.get('execution_started'):
                        raise Interrupted('Interrupted program has no saved outcome; do not execute it again')
                    attempt['executed_code']=actual
                    attempt['execution_started']=True;save()
                    def program():
                        result=execute(actual,state['input_snapshot'],folder,min(profile['program_timeout_seconds'],remaining()),config)
                        write_record(folder/'execution.json',result);return result
                    attempt['execution']=operation('program',min(profile['program_timeout_seconds'],remaining()),program)
                    attempt['executed']=True;save();checkpoint('execution_saved')
            if isolated and attempt['executed'] and not attempt['response_in_history']:
                state['messages'].append({'role':'assistant','content':attempt['response']})
                attempt['response_in_history']=True
                state['format_repair']=None;save()
            outcome=attempt['execution']
            if outcome.get('status')=='success' and outcome.get('output_openable') and remaining()>0:
                attempt['processed']=True
                state.update(actor_complete=True,termination='valid_workbook_submitted',submitted_attempt=number,output_path=outcome['output_path']);save();checkpoint('submitted');break
            attempt['processed']=True
            if isolated and not attempt['executed'] and outcome['status']=='format_error':
                attempt['repair_feedback']=protocol.format_feedback(outcome['error_detail'],profile)
                state['format_repair']={'response':attempt['response'],'feedback':deepcopy(attempt['repair_feedback'])}
            used=sum(bool(a.get('execution_started')) for a in state['attempts']) if separate else number
            if used<profile['max_code_attempts'] and remaining()>0 and attempt.get('response_in_history',True):
                msg=protocol.feedback(outcome.get('error_category','execution_error'),outcome.get('error_detail','Actor budget exhausted'),outcome.get('exit_status','unavailable'),used,profile)
                attempt['feedback_to_actor']=msg;state['messages'].append(msg)
            save();checkpoint('attempt_processed')
            if separate and not attempt['executed']:
                request_count=sum(r['code_attempt']==attempt['code_attempt'] for r in state['requests'])
                if request_count<profile['request_attempts_total'] and remaining()>0:
                    delay=min(config.get('retry_delay_seconds',0)*request_count,remaining())
                    if delay:operation('retry_wait',delay,lambda:time.sleep(delay))
        # No code path below this point appends an Actor message or calls a model.
        state['status']='scoring';save();budget_frozen=True
        score_file=directory/'score.json'
        if score_file.exists():result=json.loads(score_file.read_text())
        else:
            result=score(state['output_path'],task['answer_path'],task['answer_region'],profile)
            write_record(score_file,result);checkpoint('score_saved')
        state.update(score=result,status='completed',code_attempts=sum(a['executed'] for a in state['attempts']) if separate else len(state['attempts']),
                     program_executions=sum(a['executed'] for a in state['attempts']),api_requests=len(state['requests']))
        save();write_record(result_file,state);return result_file
    except BaseException as exc:
        state['status']='generation_incomplete' if isinstance(exc,GenerationExhausted) else ('scoring_interrupted' if state['actor_complete'] else 'technical_interruption')
        if isinstance(exc,GenerationExhausted):state['termination']='generation_budget_exhausted'
        state['error_type']=type(exc).__name__;save();raise

"""Explicit SpreadsheetBench composition boundary."""
from copy import deepcopy
from pathlib import Path
from ...facts import require
from ...contracts.diagnosis import fields
from . import protocol, actor, executor, facts, evidence, scoring

IDENTITY = {'name':'SpreadsheetBench','dataset':'Verified-400','adapter':'v25_spreadsheetbench_v1','execution_profile':'code_generation_no_score_feedback_v1'}
ROOT = Path(__file__).resolve().parents[5]


class SpreadsheetBenchAdapter:
    identity = IDENTITY

    def __init__(self, *, generate=None, execute=None, score=None):
        self.generate, self.execute, self.score = generate, execute, score

    def validate_config(self, config):
        require(config.get('benchmark') == IDENTITY, 'Explicit SpreadsheetBench identity required')
        p=config['actor_profile']
        optional=set(p)&{'attempt_budget_policy','actor_history_policy'}
        require(set(p)==set(protocol.DEFAULTS)|optional, 'Actor profile fields differ')
        require(p.get('attempt_budget_policy','responses_v1') in ('responses_v1','program_executions_v1'), 'Unknown attempt budget policy')
        require(p.get('actor_history_policy','cumulative_responses_v1') in ('cumulative_responses_v1',protocol.EXECUTION_HISTORY), 'Unknown Actor history policy')
        require(not protocol.execution_history(p) or (protocol.separate_budgets(p) and p['actor_task_timeout_seconds']==0),
                'Execution-only history requires execution budgets and no cumulative task deadline')
        fixture=config.get('dataset',{}).get('kind')=='synthetic_offline'
        expected_profile={**protocol.DEFAULTS,'actor_max_output_tokens':p['actor_max_output_tokens'],
                          'actor_task_timeout_seconds':p['actor_task_timeout_seconds'],
                          **{k:p[k] for k in optional}}
        require((p==expected_profile and p['actor_max_output_tokens'] in (16384,32768,49152)
                 and p['actor_task_timeout_seconds'] in (0,600)) or fixture,
                'Candidate Actor profile differs')
        for k,v in protocol.DEFAULTS.items():
            if isinstance(v,int):require(type(p[k]) is int and (p[k]>=0 if k=='actor_task_timeout_seconds' else p[k]>0), f'Invalid {k}')
        require(p['request_attempts_total']==config['actor_request_attempts'], 'API budget differs')
        require(config['executor']['backend']=='docker', 'Docker execution is required')
        require(config['actor_model']==config['call_config']['model'], 'Actor/method model differs')
        require(config['actor_base_url'].rstrip('/')==config['call_config']['endpoint'].removesuffix('/chat/completions'), 'Actor/method route differs')
        items=config['task_items'];require(isinstance(items,dict) and items,'Missing tasks')
        optimize=[t for b in config['batches'] for t in b];test=config['test_tasks']
        require(not set(optimize)&set(test) and set(optimize)|set(test)==set(items),'Split coverage or separation differs')
        require(len(test)==len(set(test)), 'Duplicate Test tasks')
        for key,t in items.items():
            fields(t,('id','dataset_id','split','instruction','instruction_type','answer_region','input_path','answer_path'),'Task')
            require(t['id']==key and t['split'] in ('train','val','test'), 'Invalid task identity')
            require((t['split']=='test')==(key in test), 'Test task in optimization pool')
            require(Path(t['input_path']).resolve()!=Path(t['answer_path']).resolve(), 'Answer is not an Actor input')
            try:scoring.regions(t['answer_region'])
            except ValueError:
                require(any(x['task_id']==key and x['answer_region']==t['answer_region'] for x in config['dataset'].get('metadata_issues',[])), 'Unrecorded invalid answer region')
        if not fixture:
            require(len(items)==400 and len(optimize)==120 and len(test)==280, 'Verified-400 split differs')
            require([sum(t['split']==s for t in items.values()) for s in ('train','val','test')]==[80,40,280], 'Original split differs')
            require(len(config['batches'])==8 and all(len(b)==15 for b in config['batches']), 'Expected eight batches of fifteen')
            require(config['dataset']['val_participates_in_optimization'] is True, 'Val participation must be explicit')
        require(config['initial_skill']['text'].strip(), 'Missing initial Skill')

    def resource(self,key):
        require(key==Path(key).name and (protocol.PROMPTS/key).is_file(), 'Unknown benchmark resource')
        return protocol.PROMPTS/key

    def frozen_files(self):
        return {str(p.relative_to(ROOT)):p.read_text() for p in sorted(Path(__file__).parent.rglob('*'))
                if p.is_file() and (p.suffix in ('.py','.md') or p.name=='Dockerfile')}

    build_facts=staticmethod(facts.build_facts)
    parent_text=staticmethod(facts.parent_text)
    execution_context=staticmethod(protocol.execution_context)
    actor_fields=staticmethod(protocol.render)
    runtime_snapshot=staticmethod(executor.runtime_snapshot)

    def evidence(self,operation,*args,**kwargs):
        require(operation in evidence.OPERATIONS, f'Unsupported evidence operation: {operation}')
        return evidence.OPERATIONS[operation](*args,**kwargs)

    def plan_fields(self):return ('parent','plan','runs','grouping','memory')
    def auxiliary_references(self,payload):return set()
    def validate_execution_source(self,source):
        fields(source,('run',),'Execution source');return evidence.validate_run(source['run'])
    def validation_sources(self):return {Path(evidence.__file__).resolve(),Path(facts.__file__).resolve()}
    def is_complete(self,record):return record.get('status')=='completed' and record.get('actor_complete') is True

    def actor_task(self,task,skill_file,directory,config,*,final=False):
        require(task in (config['test_tasks'] if final else [t for b in config['batches'] for t in b]), 'Task is outside this execution split')
        require(not any(x['task_id']==task for x in config['dataset'].get('metadata_issues',[])), 'Task has unresolved dataset metadata')
        scoring.regions(config['task_items'][task]['answer_region'])
        return actor.run(config['task_items'][task],Path(skill_file).read_text() if skill_file else None,directory,config,
                         generate=self.generate,execute=self.execute,score=self.score)

    def actor_command(self,*args,**kwargs):
        raise ValueError('Spreadsheet Actor uses the bounded request subprocess and Docker executor directly')

    def check_record(self,record,task,expected_skill,config):
        require(self.is_complete(record), 'Incomplete execution')
        require(record['task']==config['task_items'][task] and record['skill']==expected_skill, 'Task or Skill differs')
        require(record['model']==config['actor_model'] and record['protocol']==config['actor_profile'] and record['executor']==config['executor'],'Execution conditions differ')
        facts.build_facts([record]);return record

    def build_gate(self,parent_records,candidate_records,tasks,*,parent_skill,candidate_skill,implementation_review=None):
        facts.build_facts(parent_records);facts.build_facts(candidate_records)
        require(len(parent_records)==len(candidate_records)==len(tasks), 'Incomplete paired batch')
        p={r['task']['id']:r for r in parent_records};q={r['task']['id']:r for r in candidate_records}
        require(set(p)==set(q)==set(tasks),'Paired task set differs')
        rows=[]
        for tid in tasks:
            require(p[tid]['skill']==parent_skill and q[tid]['skill']==candidate_skill,'Gate Skill differs')
            evidence.verify_pair(p[tid],q[tid],implementation_review=implementation_review)
            rows.append({'task_id':tid,**{side:{'run_id':r['run_id'],'success':bool(r['score']['hard'])} for side,r in [('parent',p[tid]),('candidate',q[tid])]}})
        return {'input':{'pairs':rows}}

    def prepare_evaluation(self,experiment,campaign):
        from ... import evolution as ev
        config=ev.read(Path(campaign)/'config.json');self.validate_config(config)
        require(ev.read(Path(experiment)/'config/campaign.json')==config,'Evaluation experiment config differs')
        require(not config['dataset'].get('metadata_issues'), 'Resolve recorded dataset metadata issues before final Test evaluation')
        skill=ev.final_parent(campaign);require(skill is not None,'Final Skill missing')
        return {'campaign':str(Path(campaign).resolve()),'skill_text':skill.read_text(),
                'actor_config':deepcopy(config),'tasks':[config['task_items'][t] for t in config['test_tasks']],
                'initial_reference':None,'evaluation_policy':'Test only; reporting without optimization'}

    def check_evaluation_record(self,path,task,bundle):
        from ...evolution import read
        require(task in bundle['actor_config']['test_tasks'],'Not a Test task')
        return self.check_record(read(path),task,bundle['skill_text'],bundle['actor_config'])

"""Domain evidence adapter for the unchanged version-local method contracts."""
from copy import deepcopy
from pathlib import Path
import re
import json
from ...facts import require, text
from ...contracts.diagnosis import fields, links
from ...contracts import memory as mem
from ...contracts.grouping import references
from .facts import build_facts
from .protocol import execution_context, EXECUTION_HISTORY
from .timeline import model_messages
from .replay_code_view import share_code


def run_references(run):
    return {run['ref'],run['initial']['ref'],run['outcome']['ref'],*[a['ref'] for a in run['attempts']]}


def validate_run(run):
    fields(run,('ref','task_id','run_id','initial','attempts','outcome'),'Run')
    require(re.fullmatch(r'[PQ][1-9]\d*',run['ref']) is not None,'Invalid run reference')
    require(run['initial']['ref']==run['ref']+':0' and run['outcome']['ref']==run['ref']+':outcome','Invalid run references')
    filtered=any(a.get('request_context')==EXECUTION_HISTORY for a in run['attempts'])
    previous=0
    for i,a in enumerate(run['attempts'],1):
        if filtered:
            match=re.fullmatch(re.escape(run['ref'])+r':([1-9]\d*)',a['ref'])
            require(match is not None and int(match[1])>previous,'Invalid attempt reference')
            previous=int(match[1])
            require(a.get('request_context')==EXECUTION_HISTORY and a['executed'] is True,'Mixed execution evidence views')
        else:require(a['ref']==f"{run['ref']}:{i}",'Invalid attempt reference')
        require(type(a['executed']) is bool,'Invalid executed flag')
    if filtered:
        require(not {'api_requests','generation_responses'}&set(run['outcome']),'Generation counters in execution evidence')
        require(run['outcome']['submitted_attempt'] in (None,*[a['ref'] for a in run['attempts']]),'Invalid submission reference')
    require(run['outcome']['status']=='completed','Incomplete execution evidence')
    return run


def validate_grouping(result,facts):
    fields(result,('groups',),'Grouping');require(isinstance(result['groups'],list) and result['groups'],'Missing groups')
    runs={r['ref']:r for r in facts['runs']};allowed=set().union(*(run_references(r) for r in runs.values()));assigned=[];ids=set()
    for group in result['groups']:
        fields(group,('group_id','members','decision_problem','shared_basis','important_differences'),'Group')
        gid=text(group['group_id'],'Group ID');require(gid not in ids,'Duplicate Group ID');ids.add(gid)
        links(group['members'],set(runs),'Members');assigned+=group['members']
        text(group['decision_problem'],'Decision problem');text(group['shared_basis'],'Shared basis')
        require(isinstance(group['important_differences'],list),'Invalid differences')
        for item in [group['decision_problem'],group['shared_basis'],*group['important_differences']]:
            require(references(text(item,'group text'))<=allowed,'Unknown execution reference')
        for member in group['members']:
            r=runs[member];steps={a['ref'] for a in r['attempts']} or {r['initial']['ref']}
            require(bool(steps & references(group['shared_basis'])),'Group lacks decision evidence')
    require(len(assigned)==len(set(assigned)) and set(assigned)==set(runs),'Grouping must cover each run exactly once')
    return result


def diagnosis_input(saved):
    fields(saved['facts'],('parent','runs'),'Facts');validate_grouping(saved['grouping'],saved['facts'])
    return deepcopy({**saved['facts'],'grouping':saved['grouping']})


def preconditioner_input(saved,*,memory=None,memory_contract=mem.MULTI_KNOWLEDGE_CONTRACT):
    from ...contracts.diagnosis import validate_diagnosis
    facts=diagnosis_input(saved);validate_diagnosis(saved['diagnosis'],facts)
    require(saved['diagnosis']['decision']=='revise','Preconditioner needs revise')
    plan=saved['diagnosis']['plan'];encoded=json.dumps(plan);ids={r.split(':')[0] for r in references(encoded)}
    gids=set(re.findall(r'\bG\d+\b',encoded));memory=deepcopy(saved.get('memory',mem.empty_memory()) if memory is None else memory)
    mem.validate_memory(memory,memory_contract=memory_contract)
    return dict(parent=facts['parent'],plan=deepcopy(plan),runs=[deepcopy(r) for r in facts['runs'] if r['ref'] in ids],
        grouping={'groups':[deepcopy(g) for g in facts['grouping']['groups'] if g['group_id'] in gids or ids.intersection(g['members'])]},memory=memory)


def memory_view(archive,contexts,active_ids,memory_contract):
    view=mem.empty_memory()
    for mid in active_ids:
        entry=archive[mid];view['entries'].append({k:deepcopy(entry[k]) for k in ('id',*mem._entry_fields(memory_contract))})
        for ref in mem.entry_evidence(entry,memory_contract=memory_contract):
            cid,local=ref.rsplit('/',1);context=contexts[cid];payload=context['payload']
            view['sources'][cid+'/diff']={'parent':payload['parent'],'diff':payload['diff'],'execution_context':deepcopy(context['execution_context'])}
            if local!='diff':
                rid=local.split(':')[0];run=next(r for r in payload['runs'] if r['ref']==rid)
                require(local in run_references(run),'Historical source missing')
                view['sources'][cid+'/'+rid]={'run':deepcopy(run)}
    mem.validate_memory(view,memory_contract=memory_contract);return view


def verify_pair(parent,candidate,*,implementation_review=None):
    require(implementation_review is None,'No runtime implementation amendments')
    for key in ('task','model','protocol','executor'):require(parent[key]==candidate[key],f'Pair {key} differs')
    require(parent['run_id']!=candidate['run_id'],'Pair reuses execution identity')
    require(Path(parent['input_snapshot']).read_bytes()==Path(candidate['input_snapshot']).read_bytes(),'Paired original inputs differ')
    require(parent['initial_messages'][1:]==candidate['initial_messages'][1:],'Paired task messages differ')


def pair_result(run):
    o=run['outcome'];return {k:o[k] for k in ('status','code_attempts','program_executions','api_requests') if k in o}|{k:o['score'][k] for k in ('hard','per_cell_pass_rate')}


def relabel(run,ref):
    run=deepcopy(run);run['ref']=ref;run['initial']['ref']=ref+':0';run['outcome']['ref']=ref+':outcome'
    for a in run['attempts']:a['ref']=ref+':'+a['ref'].split(':')[-1]
    if run['outcome']['submitted_attempt']:run['outcome']['submitted_attempt']=ref+':'+run['outcome']['submitted_attempt'].split(':')[-1]
    return run


def build_replay_from_editor(saved,editor_directory,parent_records,candidate_records,*,memory=None,implementation_review=None,memory_contract=mem.MULTI_KNOWLEDGE_CONTRACT,facts_builder=build_facts,pair_verifier=verify_pair):
    from ...contracts.editor import apply_patch
    require(saved['editor_status']=='candidate','Replay needs real Candidate')
    require(apply_patch(saved['facts']['parent'],saved['actual_diff'])==saved['candidate_text'],'Actual Diff differs')
    p,q=facts_builder(parent_records),facts_builder(candidate_records)
    require(p['facts']==saved['facts'] and p['background']==q['background']==saved['background'],'Frozen Parent lineage differs')
    require(q['facts']['parent']==saved['candidate_text'],'Executed Candidate differs')
    require(len(parent_records)==len(candidate_records),'Incomplete pairs')
    candidates={r['task']['id']:(r,run) for r,run in zip(candidate_records,q['facts']['runs'])}
    runs=deepcopy(p['facts']['runs']);pairs=[];audits=[]
    for i,(record,prun) in enumerate(zip(parent_records,p['facts']['runs']),1):
        require(record['task']['id'] in candidates,'Missing Candidate task')
        qr,qrun=candidates[record['task']['id']];pair_verifier(record,qr,implementation_review=implementation_review)
        qrun=relabel(qrun,f'Q{i}');runs.append(qrun)
        pair=dict(parent=prun['ref'],candidate=qrun['ref'],task_id=prun['task_id'],parent_result=pair_result(prun),candidate_result=pair_result(qrun));pairs.append(pair)
        audits.append({'pair':{'parent':prun['ref'],'candidate':qrun['ref']},'task_id':prun['task_id'],'parent_run_id':record['run_id'],'candidate_run_id':qr['run_id'],'verified':True})
    plan=saved['effective_plan'];plan={'goal':plan['goal'],'updates':[{k:u[k] for k in ('id','text')} for u in plan['updates']],'checks':deepcopy(plan['checks'])}
    payload=dict(parent=p['facts']['parent'],diff=saved['actual_diff'],plan=plan,runs=runs,pairs=pairs,memory=deepcopy(memory if memory is not None else mem.empty_memory()))
    validate_payload(payload,memory_contract=memory_contract)
    return dict(payload=payload,background=p['background'],pair_audit=audits,editor_directory=str(Path(editor_directory).resolve()),candidate=saved['candidate_text'],
                execution_context={'background':p['background'],'description':execution_context(p['background']),'actor_model':parent_records[0]['model'],'protocol':parent_records[0]['protocol']})


def validate_payload(payload,*,memory_contract=mem.MULTI_KNOWLEDGE_CONTRACT):
    from ...contracts.editor import apply_patch
    fields(payload,('parent','diff','plan','runs','pairs','memory'),'Replay input');apply_patch(payload['parent'],payload['diff'])
    plan=payload['plan'];fields(plan,('goal','updates','checks'),'Plan');text(plan['goal'],'goal');require(bool(plan['updates']),'Missing Updates')
    ids=set()
    for u in plan['updates']:
        fields(u,('id','text'),'Update');text(u['id'],'ID');text(u['text'],'text');require(u['id'] not in ids,'Duplicate Update');ids.add(u['id'])
    cids=set()
    for c in plan['checks']:
        fields(c,('id','update_ids','question'),'Check');require(c['id'] not in ids|cids,'Duplicate Check');cids.add(c['id']);text(c['question'],'Question');links(c['update_ids'],ids,'Check updates')
    runs={r['ref']:validate_run(r) for r in payload['runs']};require(len(runs)==len(payload['runs']) and runs,'Duplicate/missing runs')
    paired=[];tasks=set()
    for pair in payload['pairs']:
        fields(pair,('parent','candidate','task_id','parent_result','candidate_result'),'Pair')
        require(pair['task_id'] not in tasks,'Duplicate paired task');tasks.add(pair['task_id'])
        for side,prefix in [('parent','P'),('candidate','Q')]:
            ref=pair[side];require(ref in runs and ref.startswith(prefix),'Invalid pair role')
            require(runs[ref]['task_id']==pair['task_id'] and pair[side+'_result']==pair_result(runs[ref]),'Pair task/result differs');paired.append(ref)
    require(len(paired)==len(set(paired)) and set(paired)==set(runs),'Pair coverage differs')
    mem.validate_memory(payload['memory'],memory_contract=memory_contract);return payload


def current_pairs(bundle):
    payload=validate_payload(bundle['payload']);audits=bundle['pair_audit'];require(len(audits)==len(payload['pairs']),'Pair audit missing')
    runs={r['ref']:r for r in payload['runs']}
    for pair,a in zip(payload['pairs'],audits):
        require(a['verified'] and a['task_id']==pair['task_id'] and a['pair']=={k:pair[k] for k in ('parent','candidate')},'Pair audit differs')
        require(a['parent_run_id']==runs[pair['parent']]['run_id'] and a['candidate_run_id']==runs[pair['candidate']]['run_id'],'Execution identity differs')
    return deepcopy(payload['pairs']),deepcopy(payload['runs'])


def model_input(bundle,*,memory_contract=mem.MULTI_KNOWLEDGE_CONTRACT):
    from ...memory_view import knowledge_only
    payload=validate_payload(bundle['payload'],memory_contract=memory_contract);current_pairs(bundle)
    return {k:deepcopy(v) for k,v in payload.items() if k!='memory'}|{'memory':knowledge_only(payload['memory'],memory_contract=memory_contract)}


def validate_bundle(bundle,*,memory_contract=mem.MULTI_KNOWLEDGE_CONTRACT):
    from ...editor import load_editor
    validate_payload(bundle['payload'],memory_contract=memory_contract);current_pairs(bundle);saved=load_editor(bundle['editor_directory']);p=bundle['payload']
    require(saved['editor_status']=='candidate' and bundle['candidate']==saved['candidate_text'] and p['diff']==saved['actual_diff'],'Replay edit lineage differs')
    require(p['parent']==saved['facts']['parent'] and bundle['background']==saved['background'],'Replay background differs')
    require([r for r in p['runs'] if r['ref'].startswith('P')]==saved['facts']['runs'],'Parent replay records differ')
    plan=saved['effective_plan'];expected={'goal':plan['goal'],'updates':[{k:u[k] for k in ('id','text')} for u in plan['updates']],'checks':plan['checks']}
    require(p['plan']==expected,'Replay Plan differs');return bundle


def extract(ref,bundle,historical):
    source=bundle;local=ref;history=None
    if '/' in ref:history,local=ref.rsplit('/',1);source=historical[history]
    current_pairs(source);p=source['payload']
    if local=='diff':return {'parent':p['parent'],'diff':p['diff'],'execution_context':deepcopy(source['execution_context'])}
    rid,_,suffix=local.partition(':');run=next(r for r in p['runs'] if r['ref']==rid)
    if not suffix:record=run
    elif suffix=='0':record=run['initial']
    elif suffix=='outcome':record=run['outcome']
    else:record=next(a for a in run['attempts'] if a['ref']==local)
    value={'task_id':run['task_id'],'run_id':run['run_id'],'role':'parent' if rid.startswith('P') else 'candidate','record':deepcopy(record)}
    if history:value['execution_context']=deepcopy(source['execution_context'])
    return value


def build_input(bundle,candidate,historical=None):
    from ...knowledge_evidence import select_targets
    from ...replay import validate_result
    historical=historical or {};p=validate_payload(bundle['payload']);validate_result(candidate,p)
    targets,inventory=select_targets(candidate,p['memory']);refs=list(dict.fromkeys(ref for t in targets for ref in t['knowledge']['evidence']))
    for cid in {ref.rsplit('/',1)[0] for ref in refs if '/' in ref}:
        prior=historical[cid];current_pairs(prior)
        for key,original in p['memory']['sources'].items():
            if key.rsplit('/',1)[0]!=cid:continue
            local=key.rsplit('/',1)[1]
            expected=extract(key,bundle,historical) if local=='diff' else {'run':next(r for r in prior['payload']['runs'] if r['ref']==local)}
            require(original==expected,'Historical source differs')
    cited={x.split(':')[0] for x in refs if '/' not in x and x!='diff'}
    pairs=[{k:pair[k] for k in ('parent','candidate','task_id')} for pair in p['pairs'] if pair['parent'] in cited or pair['candidate'] in cited]
    value={'context':{'parent':p['parent'],'diff':p['diff'],'execution_context':deepcopy(bundle['execution_context']),'pairs':pairs},'targets':targets,'source_records':{ref:extract(ref,bundle,historical) for ref in refs}}
    return value,inventory


def compact(value):
    fields(value,('context','targets','source_records'),'Knowledge input');return deepcopy(value)


def build_repair_input(value,verdicts,candidate):
    from ... import knowledge_verifier as v,knowledge_repair as repair
    v.validate_result(verdicts,value);original={v.position(t['target'],'target'):t for t in value['targets']};targets=[];refs=set()
    for row in verdicts['results']:
        if row['verdict']!='CONFLICT':continue
        ei,ki=key=v.position(row['target'],'target');t=deepcopy(original[key]);require(t['knowledge']==candidate['entries'][ei]['knowledge'][ki],'Target differs')
        t['issues']=deepcopy(row['issues']);targets.append(t);refs.update(t['knowledge']['evidence'])
        for issue in row['issues']:refs.update(issue['evidence'])
    context=deepcopy(value['context']);rids={r.split(':')[0] for r in refs if '/' not in r and r!='diff'}
    context['pairs']=[p for p in context['pairs'] if p['parent'] in rids or p['candidate'] in rids]
    return {'context':context,'targets':targets,'source_records':{r:deepcopy(value['source_records'][r]) for r in sorted(refs)}}


OPERATIONS={
'replay_view.share_code':share_code,
'model_input.timeline_messages':model_messages,
'contracts.grouping.validate_grouping':validate_grouping,'contracts.diagnosis.diagnosis_input':diagnosis_input,
'contracts.preconditioner.preconditioner_input':preconditioner_input,
'contracts.memory.run_references':run_references,'contracts.memory.validate_run':validate_run,'contracts.memory._view':memory_view,
'contracts.replay.verify_pair':verify_pair,'contracts.replay.build_replay_from_editor':build_replay_from_editor,'contracts.replay.validate_payload':validate_payload,
'contracts.replay_view._current_pairs':current_pairs,'replay_view.model_input':model_input,'replay.validate_bundle':validate_bundle,
'knowledge_evidence.extract':extract,'knowledge_evidence.build_input':build_input,
'knowledge_evidence.compact':compact,'knowledge_evidence.restore':compact,'knowledge_evidence.build_repair_input':build_repair_input}

"""Disposable, offline Docker program execution. Only input and attempt files mount."""
import json
from pathlib import Path
import shutil
import subprocess
import uuid
import openpyxl


class InfrastructureError(RuntimeError):
    pass


RUNNER = '''import sys
INPUT_PATH = "/work/input.xlsx"
OUTPUT_PATH = "/work/output/result.xlsx"
import openpyxl, pandas

def policy(event, args):
    if event.startswith(("subprocess.", "socket.", "os.exec", "os.spawn")) or event in ("os.system", "os.fork", "os.forkpty"):
        raise PermissionError("Network and external command execution are unavailable")
sys.addaudithook(policy)
with open("/work/program.py") as source:
    code = compile(source.read(), "solution.py", "exec")
exec(code, {"__name__": "__main__", "INPUT_PATH": INPUT_PATH, "OUTPUT_PATH": OUTPUT_PATH})
'''


def runtime_snapshot(config):
    image = config['executor']['image']
    code = 'import sys,json,importlib.metadata as m;print(json.dumps({"python":sys.version,"packages":{n:m.version(n) for n in ["openpyxl","pandas","numpy"]}}))'
    try:
        proc = subprocess.run(['docker','run','--rm','--network','none',image,'python','-c',code], capture_output=True,text=True,timeout=30)
        if proc.returncode: raise InfrastructureError('Docker image/runtime is unavailable')
        return {'backend':'docker', 'image':image, **json.loads(proc.stdout)}
    except (OSError, subprocess.TimeoutExpired, ValueError) as exc:
        raise InfrastructureError('Cannot inspect execution runtime') from exc


def execute(code, input_path, directory, timeout, config):
    directory = Path(directory).resolve(); directory.mkdir(parents=True,exist_ok=True)
    output = directory/'output'; output.mkdir(exist_ok=True); output.chmod(0o777)
    for name, content in [('program.py',code),('runner.py',RUNNER)]:
        (directory/name).write_text(content); (directory/name).chmod(0o644)
    shutil.copyfile(input_path,directory/'input.xlsx'); (directory/'input.xlsx').chmod(0o644)
    name = 'v25-'+uuid.uuid4().hex[:16]
    args = ['docker','run','--rm','--name',name,'--network','none','--read-only',
            '--cap-drop','ALL','--security-opt','no-new-privileges','--pids-limit','64',
            '--memory',config['executor']['memory'],'--cpus',str(config['executor']['cpus']),
            '--user','65534:65534','--tmpfs','/tmp:rw,nosuid,nodev,size=64m',
            '-e','PYTHONDONTWRITEBYTECODE=1','-e','OPENBLAS_NUM_THREADS=1']
    for filename in ('program.py','runner.py','input.xlsx'):
        args += ['--mount',f'type=bind,src={directory/filename},dst=/work/{filename},readonly']
    args += ['--mount',f'type=bind,src={output},dst=/work/output',config['executor']['image'],'python','/work/runner.py']
    try:
        with (directory/'stdout.txt').open('w') as stdout, (directory/'stderr.txt').open('w') as stderr:
            proc = subprocess.run(args,stdout=stdout,stderr=stderr,timeout=timeout)
        status, exit_status = 'success', proc.returncode
    except subprocess.TimeoutExpired:
        status, exit_status = 'timeout', None
    except OSError as exc:
        raise InfrastructureError('Cannot launch Docker executor') from exc
    finally:
        subprocess.run(['docker','rm','-f',name],capture_output=True,timeout=15)
    stdout=(directory/'stdout.txt').read_text(errors='replace'); stderr=(directory/'stderr.txt').read_text(errors='replace')
    if exit_status in (125,126,127): raise InfrastructureError(f'Execution infrastructure exited {exit_status}')
    result={'status':status,'exit_status':exit_status,'stdout':stdout,'stderr':stderr,'output_openable':False}
    if status=='timeout': return {**result,'error_category':'execution_error','error_detail':'Program execution timed out.\n'+stderr}
    if exit_status != 0: return {**result,'status':'error','error_category':'execution_error','error_detail':stderr or stdout}
    path=output/'result.xlsx'
    # Reject links instead of inspecting a different host file after execution.
    if not path.is_file() or path.is_symlink():
        return {**result,'status':'error','error_category':'output_file_error','error_detail':'Output workbook is missing or is not a regular file'}
    try:
        wb=openpyxl.load_workbook(path); wb.close()
    except Exception:
        return {**result,'status':'error','error_category':'output_file_error','error_detail':'Output workbook cannot be opened as .xlsx'}
    return {**result,'output_openable':True,'output_path':str(path)}

