"""Share only an unchanged executed program with its own complete response."""
from copy import deepcopy

from ...facts import require
from .protocol import extract_code

MARKER = {'from_response': 'python_fence_body_exact_v1'}


def unchanged_body(attempt):
    if attempt.get('executed') is not True or not isinstance(attempt.get('response'), str):
        return None
    try:
        raw, actual = extract_code(attempt['response'])
    except (ValueError, SyntaxError):
        return None
    # In particular, path adaptation must never be hidden behind this marker.
    return raw if raw == actual else None


def share_code(view):
    result = deepcopy(view)
    for run in result['runs']:
        for attempt in run['attempts']:
            code = attempt['executed_code']
            require(code is None or isinstance(code, str), 'Replay code already shared or invalid')
            if isinstance(code, str) and unchanged_body(attempt) == code:
                attempt['executed_code'] = deepcopy(MARKER)
    return result


def restore_code(view):
    result = deepcopy(view)
    for run in result['runs']:
        for attempt in run['attempts']:
            code = attempt['executed_code']
            if code is None or isinstance(code, str):
                continue
            require(code == MARKER, 'Invalid Replay shared code marker')
            body = unchanged_body(attempt)
            require(body is not None, 'Replay shared code requires an unchanged executed response body')
            attempt['executed_code'] = body
    return result

"""Saved-value scoring, following the local SkillOpt/SkillAdam comparison semantics.

No formula engine and no expected-value strings in the returned score view.
"""
import datetime
import re
import openpyxl
from openpyxl.utils.cell import range_boundaries, get_column_letter


def transform(value):
    if isinstance(value, (bool, int, float)):
        return round(float(value), 2)
    if isinstance(value, datetime.time):
        return str(value)[:-3]
    if isinstance(value, datetime.datetime):
        delta = value-datetime.datetime(1899, 12, 30)
        return round(delta.days+delta.seconds/86400.0, 0)
    if isinstance(value, str):
        try: return round(float(value), 2)
        except ValueError: pass
    return value


def equal(a, b):
    a, b = transform(a), transform(b)
    if a in ('', None) and b in ('', None): return True
    return type(a) is type(b) and a == b


def regions(answer_region):
    # Each region has an explicit sheet and range. A comma before ! belongs to
    # the sheet name; one after the cell range starts the next region. Edge
    # quotes tolerate the existing dataset's loosely quoted coordinates.
    result = [];rest=answer_region.strip()
    while rest:
        match=re.match(r'(.+?)!([^,]+)(?:,|$)',rest)
        if match is None:raise ValueError('Invalid explicit answer region')
        sheet,cells=match.groups();rest=rest[match.end():]
        if not sheet.strip() or not cells.strip():raise ValueError('Invalid explicit answer region')
        sheet = sheet.strip().strip("'\"").replace("''", "'")
        cells = cells.strip().strip("'\"")
        # Dataset shorthand: BD2:308 means BD2:BD308, never an empty range.
        shorthand=re.fullmatch(r'([A-Za-z]+)([1-9][0-9]*):([1-9][0-9]*)',cells)
        if shorthand:
            col,start,end=shorthand.groups();cells=f'{col}{start}:{col}{end}'
        bounds = range_boundaries(cells)
        if re.fullmatch(r'[A-Za-z]+:[A-Za-z]+',cells):
            # Resolve the final row against BOTH workbooks in score().
            if bounds[2]<bounds[0]:raise ValueError('Reversed column range')
            result.append((sheet,(bounds[0],1,bounds[2],None)));continue
        if any(v is None for v in bounds) or min(bounds)<1 or bounds[2] < bounds[0] or bounds[3] < bounds[1]:
            raise ValueError('Invalid bounded answer region')
        result.append((sheet, bounds))
    if not result: raise ValueError('Empty answer region')
    return result


def score(output, answer, answer_region, profile):
    gold = openpyxl.load_workbook(answer, data_only=True)
    pred = None
    try:
        if output is not None: pred = openpyxl.load_workbook(output, data_only=True)
        correct, total, wrong, missing = 0, 0, [], []
        for sheet, (c1, r1, c2, r2) in regions(answer_region):
            if sheet not in gold.sheetnames: raise ValueError('Answer region worksheet missing from reference')
            absent = pred is None or sheet not in pred.sheetnames
            if r2 is None:
                r2=max(gold[sheet].max_row or 1,1 if absent else (pred[sheet].max_row or 1))
            if absent and sheet not in missing: missing.append(sheet)
            for col in range(c1, c2+1):
                for row in range(r1, r2+1):
                    total += 1
                    if not absent and equal(gold[sheet].cell(row,col).value, pred[sheet].cell(row,col).value):
                        correct += 1
                    else: wrong.append(f'{sheet}!{get_column_letter(col)}{row}')
        result = dict(hard=int(correct == total), per_cell_pass_rate=round(correct/total,4),
                      correct_cells=correct, total_cells=total,
                      mismatched_cells=wrong, mismatched_cells_total=len(wrong),
                      missing_sheets=missing, missing_sheets_total=len(missing))
        return result
    finally:
        gold.close()
        if pred is not None: pred.close()


def model_view(result, profile):
    return {**result, 'mismatched_cells': result['mismatched_cells'][:profile['score_coordinate_limit']],
            'missing_sheets': result['missing_sheets'][:profile['score_missing_sheet_limit']]}

"""One live request per child process; parent imposes an absolute wall timeout."""
import json
import os
from pathlib import Path
import subprocess
import sys
from ...storage import write_record


class RequestError(RuntimeError):
    def __init__(self, message, retryable=True):
        super().__init__(message); self.retryable=retryable


def request(messages, directory, timeout, config):
    directory=Path(directory)
    public={'messages':messages,'call_config':{**config['call_config'],'max_tokens':config['actor_profile']['actor_max_output_tokens']},'timeout':timeout}
    write_record(directory/'request.json',public)
    try:
        proc=subprocess.run([sys.executable,'-m',__name__,'--once',str(directory)],capture_output=True,text=True,timeout=timeout)
    except subprocess.TimeoutExpired as exc:
        raise RequestError('API request timed out') from exc
    if (directory/'response.json').exists():return json.loads((directory/'response.json').read_text())
    if (directory/'request_error.json').exists():
        error=json.loads((directory/'request_error.json').read_text())
        raise RequestError(error['error'],error['retryable'])
    raise RequestError(f'API worker exited {proc.returncode} without a saved response',False)


def once(directory):
    import requests
    from urllib.parse import urlsplit
    directory=Path(directory);saved=json.loads((directory/'request.json').read_text());cfg=saved['call_config']
    key=os.environ.get('OPENAI_API_KEY')
    if not key:raise RequestError('OPENAI_API_KEY is not configured',False)
    body={k:cfg[k] for k in ('model','max_tokens','temperature','reasoning_effort','thinking','stream')}
    body['messages']=saved['messages']
    with requests.Session() as session:
        if '.intra.' in (urlsplit(cfg['endpoint']).hostname or ''):session.trust_env=False
        raw=session.post(cfg['endpoint'],headers={'Authorization':f'Bearer {key}'},json=body,
                         timeout=(min(10,saved['timeout']),saved['timeout']),allow_redirects=False)
    write_record(directory/'http_status.json',{'status_code':raw.status_code})
    if not 200<=raw.status_code<300:
        raise RequestError(f'API returned HTTP {raw.status_code}',raw.status_code in (408,429,500,502,503,504))
    try:
        data=raw.json();choice=data['choices'][0]
        result={'content':choice['message'].get('content') or '', 'finish_reason':choice['finish_reason'],
                'response_model':data.get('model'),'usage':data.get('usage')}
        if not isinstance(result['content'],str):raise ValueError()
    except (ValueError,KeyError,TypeError,IndexError) as exc:raise RequestError('Malformed API response') from exc
    write_record(directory/'response.json',result)


if __name__=='__main__':
    folder=Path(sys.argv[2])
    try:once(folder)
    except Exception as exc:
        retryable=isinstance(exc,RequestError) and exc.retryable
        if type(exc).__name__ in ('Timeout','ReadTimeout','ConnectTimeout','ConnectionError','ChunkedEncodingError'):retryable=True
        write_record(folder/'request_error.json',{'error':str(exc) if isinstance(exc,RequestError) else type(exc).__name__,'retryable':retryable})
        sys.exit(1)

